export default "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#0B2A4A\">\n<meta name=\"description\" content=\"PharmaCheck Admin — provision pharmacies and manage their accounts.\">\n<title>PharmaCheck Admin</title>\n<link rel=\"icon\" href=\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><rect width='32' height='32' rx='8' fill='%230B2A4A'/><path d='M10 9h8a5 5 0 0 1 0 10h-4v5h-4z' fill='white'/></svg>\">\n<style>\n/* =====================================================================\n   PharmaCheck Admin — styles\n\n   The same design language as the pharmacy app, in a darker key. The\n   pharmacy app is a tool people use all day at a counter; this one is\n   used occasionally, by one person, to do things that are hard to\n   undo — so it reads as an instrument panel rather than a shop floor.\n   ===================================================================== */\n:root {\n  --navy-900: #071B30;\n  --navy-800: #0B2A4A;\n  --navy-700: #103A63;\n  --blue-100: #E4EFFC;\n  --blue-200: #C9DFF8;\n  --blue-500: #1A73E8;\n  --blue-600: #1568D6;\n  --blue-700: #1360C9;\n\n  --ink:      #0C1A28;\n  --muted:    #6C8199;\n  --line:     #E1EAF4;\n  --page:     #F1F5FA;\n\n  --green:    #0FA45C;\n  --green-2:  #0C8A4D;\n  --green-bg: #E4F7ED;\n  --red:      #E03B45;\n  --red-bg:   #FDEBEC;\n  --amber:    #E08A00;\n  --amber-bg: #FDF2DF;\n\n  --tab-h: 62px;\n  --radius: 18px;\n}\n\n* { box-sizing: border-box; margin: 0; padding: 0; }\n\n/* The `hidden` attribute is how this app shows and hides things from JS,\n   and any author rule that sets `display` silently beats the browser's\n   own [hidden] style — a class like .tabbar { display: grid } would keep\n   a \"hidden\" element on screen. This makes the attribute win. */\n[hidden] { display: none !important; }\n\nhtml, body { height: 100%; }\n\n/* Pinned rather than merely `overflow: hidden`.\n   A sheet sits inside the phone translated fully below it, so focusing a\n   field in one asks the browser to scroll it into view — and it will\n   scroll the *document* to do it, which slides the whole phone frame up\n   and leaves the sheets rendering below it. Overflow hidden does not stop\n   a programmatic scroll; taking the body out of flow does. */\nbody {\n  font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, \"Helvetica Neue\", Arial, sans-serif;\n  background: #DDE6F1;\n  color: var(--ink);\n  -webkit-font-smoothing: antialiased;\n  position: fixed;\n  inset: 0;\n  overflow: hidden;\n}\n\n.sprite { display: none; }\n\n.icon {\n  width: 22px;\n  height: 22px;\n  fill: none;\n  stroke: currentColor;\n  stroke-width: 1.8;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n  flex: none;\n}\n.icon--xs { width: 14px; height: 14px; stroke-width: 2.1; }\n\nbutton { font: inherit; color: inherit; }\ninput { font: inherit; color: inherit; }\n\n/* ------------------------------------------------------------- shell */\n.stage {\n  min-height: 100%;\n  display: grid;\n  place-items: center;\n  padding: 28px 16px;\n}\n\n.phone {\n  width: 390px;\n  height: 844px;\n  max-height: calc(100vh - 56px);\n  background: var(--page);\n  border-radius: 42px;\n  border: 10px solid #0A121C;\n  box-shadow: 0 30px 70px rgba(9, 24, 43, .38);\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  position: relative;\n}\n\n/* On a real phone the frame is the phone. */\n@media (max-width: 460px), (max-height: 720px) {\n  .stage { padding: 0; }\n  .phone {\n    width: 100%;\n    height: 100%;\n    max-height: none;\n    border: 0;\n    border-radius: 0;\n    box-shadow: none;\n  }\n}\n\nhtml.is-native .stage { padding: 0; }\nhtml.is-native .phone {\n  width: 100%;\n  height: 100%;\n  max-height: none;\n  border: 0;\n  border-radius: 0;\n  box-shadow: none;\n}\nhtml.is-native .statusbar,\nhtml.is-native .homebar { display: none; }\n\n.statusbar {\n  flex: none;\n  height: 44px;\n  padding: 0 26px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  font-size: 14px;\n  font-weight: 680;\n  color: var(--ink);\n}\n.sb-right { display: flex; align-items: center; gap: 5px; }\n.sb-right svg { height: 11px; fill: currentColor; }\n\n.homebar {\n  flex: none;\n  height: 22px;\n  background: rgba(255, 255, 255, .92);\n  position: relative;\n  z-index: 10;\n}\n.homebar::after {\n  content: \"\";\n  position: absolute;\n  left: 50%;\n  top: 3px;\n  transform: translateX(-50%);\n  width: 134px;\n  height: 5px;\n  border-radius: 5px;\n  background: #0B1524;\n  opacity: .82;\n}\n\n/* ----------------------------------------------------------- screens */\n.viewport { flex: 1; position: relative; overflow: hidden; }\n\n.screen {\n  position: absolute;\n  inset: 0;\n  display: none;\n  flex-direction: column;\n  padding: 4px 18px 18px;\n}\n.screen.is-active { display: flex; }\n.screen--scroll { overflow-y: auto; -webkit-overflow-scrolling: touch; }\n.screen--fixed { overflow: hidden; }\n\n.apphead {\n  display: flex;\n  align-items: flex-start;\n  gap: 12px;\n  padding: 14px 0 18px;\n}\n.apphead--compact { padding: 12px 0 14px; align-items: center; }\n.apphead > div { flex: 1; min-width: 0; }\n.apphead__date { font-size: 12px; font-weight: 620; color: var(--muted); }\n.apphead__title { font-size: 27px; font-weight: 780; letter-spacing: -.7px; }\n.apphead__title--sm { font-size: 21px; letter-spacing: -.5px; }\n.apphead__sub {\n  font-size: 12.5px;\n  font-weight: 560;\n  color: var(--muted);\n  margin-top: 3px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n/* flex:none, because `.apphead > div` above matches this container too —\n   without it the actions share the free space and the button drifts into\n   the middle of the header instead of sitting at the end. */\n.apphead__actions { display: flex; gap: 8px; align-items: center; flex: none; }\n\n.iconbtn {\n  width: 40px;\n  height: 40px;\n  border: 0;\n  border-radius: 13px;\n  display: grid;\n  place-items: center;\n  cursor: pointer;\n  flex: none;\n  transition: transform .12s ease, background .16s ease;\n}\n.iconbtn:active { transform: scale(.92); }\n.iconbtn--ghost { background: #fff; color: var(--navy-800); box-shadow: 0 2px 8px rgba(11, 42, 74, .08); }\n\n.section-head {\n  display: flex;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 10px;\n  margin: 22px 0 10px;\n}\n.section-title { font-size: 15.5px; font-weight: 720; letter-spacing: -.3px; }\n\n.linkbtn {\n  border: 0;\n  background: none;\n  color: var(--blue-600);\n  font-size: 12.5px;\n  font-weight: 680;\n  cursor: pointer;\n  display: inline-flex;\n  align-items: center;\n  gap: 3px;\n  padding: 2px;\n}\n\n/* Numbered steps make Settings read as a sequence rather than a pile of\n   fields — it is the screen an operator visits once and must not misread. */\n.steprow {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  margin: 24px 0 10px;\n}\n.stepnum {\n  flex: none;\n  width: 24px;\n  height: 24px;\n  border-radius: 50%;\n  display: grid;\n  place-items: center;\n  background: var(--navy-800);\n  color: #fff;\n  font-size: 12px;\n  font-weight: 760;\n}\n.steprow .section-title { margin: 0; }\n\n/* ------------------------------------------------------------- cards */\n.card {\n  background: #fff;\n  border-radius: var(--radius);\n  padding: 16px;\n  box-shadow: 0 2px 10px rgba(11, 42, 74, .05);\n}\n\n.statgrid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 10px;\n}\n.statgrid--tight { gap: 9px; }\n\n.stat { padding: 14px 15px; }\n.stat__label {\n  font-size: 11px;\n  font-weight: 640;\n  color: var(--muted);\n  text-transform: uppercase;\n  letter-spacing: .4px;\n}\n.stat__value { font-size: 25px; font-weight: 780; letter-spacing: -.8px; margin-top: 5px; }\n.stat__meta { font-size: 11.5px; font-weight: 560; color: var(--muted); margin-top: 2px; }\n\n.cardlist { list-style: none; display: flex; flex-direction: column; gap: 9px; }\n.cardlist--scroll { flex: 1; overflow-y: auto; padding-bottom: 90px; }\n\n.rowcard {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  width: 100%;\n  text-align: left;\n  background: #fff;\n  border: 0;\n  border-radius: 15px;\n  padding: 14px;\n  cursor: pointer;\n  box-shadow: 0 2px 10px rgba(11, 42, 74, .05);\n  transition: transform .12s ease;\n}\n.rowcard:active { transform: scale(.99); }\n\n.rowcard__badge {\n  flex: none;\n  width: 42px;\n  height: 42px;\n  border-radius: 13px;\n  display: grid;\n  place-items: center;\n  background: linear-gradient(155deg, var(--navy-700), var(--navy-900));\n  color: #fff;\n  font-size: 14px;\n  font-weight: 760;\n  letter-spacing: -.4px;\n}\n.rowcard__badge--vendor { background: linear-gradient(150deg, #2FC5B8, #0FA3A3); }\n.rowcard__badge--mgr { background: linear-gradient(155deg, #4A9BF7, var(--blue-700)); }\n.rowcard__badge--off { background: #C3D0DE; color: #6C8199; }\n\n.rowcard__body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 3px; }\n.rowcard__name {\n  font-size: 14.5px;\n  font-weight: 700;\n  letter-spacing: -.2px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.rowcard__meta { font-size: 11.5px; font-weight: 560; color: var(--muted); }\n.rowcard__go { color: #B4C4D6; }\n\n.pill {\n  display: inline-block;\n  padding: 2.5px 8px;\n  border-radius: 999px;\n  font-size: 9.5px;\n  font-weight: 740;\n  letter-spacing: .3px;\n  text-transform: uppercase;\n}\n.pill--ok { background: var(--green-bg); color: var(--green-2); }\n.pill--off { background: var(--red-bg); color: var(--red); }\n.pill--warn { background: var(--amber-bg); color: var(--amber); }\n.pill--info { background: var(--blue-100); color: var(--blue-700); }\n\n.emptynote {\n  padding: 22px 16px;\n  text-align: center;\n  font-size: 12.5px;\n  font-weight: 560;\n  color: var(--muted);\n  background: #fff;\n  border-radius: 15px;\n  line-height: 1.55;\n}\n\n.dbcard { display: flex; align-items: center; gap: 13px; }\n.dbcard__icon { color: var(--navy-700); width: 26px; height: 26px; }\n.dbcard__body { min-width: 0; }\n.dbcard__name {\n  font-family: ui-monospace, \"SF Mono\", Menlo, monospace;\n  font-size: 13px;\n  font-weight: 640;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n.dbcard__meta { font-size: 11.5px; font-weight: 560; color: var(--muted); margin-top: 2px; }\n\n.connectcard { display: flex; flex-direction: column; gap: 12px; }\n.connectcard__note { font-size: 12px; font-weight: 560; color: var(--muted); line-height: 1.5; }\n\n.kv { display: flex; flex-direction: column; gap: 9px; }\n.kv__row { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; }\n.kv__row dt { font-size: 12px; font-weight: 620; color: var(--muted); flex: none; }\n.kv__row dd {\n  font-family: ui-monospace, \"SF Mono\", Menlo, monospace;\n  font-size: 12px;\n  font-weight: 620;\n  text-align: right;\n  overflow-wrap: anywhere;\n}\n\n/* --------------------------------------------------------- checklist */\n.checklist { list-style: none; display: flex; flex-direction: column; gap: 0; }\n\n.chk {\n  display: grid;\n  grid-template-columns: auto 1fr auto;\n  gap: 3px 11px;\n  align-items: center;\n  padding: 12px 0;\n  border-bottom: 1px solid var(--line);\n}\n.chk:first-child { padding-top: 2px; }\n.chk:last-child { border-bottom: 0; padding-bottom: 2px; }\n\n.chk__dot {\n  width: 20px;\n  height: 20px;\n  border-radius: 50%;\n  display: grid;\n  place-items: center;\n  color: #fff;\n}\n.chk__dot--ok { background: var(--green); }\n.chk__dot--no { background: var(--red); }\n.chk__name { font-size: 13px; font-weight: 660; }\n.chk__why {\n  grid-column: 2 / -1;\n  font-size: 11.5px;\n  font-weight: 540;\n  color: var(--muted);\n  line-height: 1.5;\n}\n\ncode {\n  font-family: ui-monospace, \"SF Mono\", Menlo, monospace;\n  font-size: 10.5px;\n  background: var(--blue-100);\n  color: var(--blue-700);\n  padding: 1.5px 5px;\n  border-radius: 5px;\n}\n\n/* ------------------------------------------------------------ fields */\n.setform { display: flex; flex-direction: column; gap: 15px; }\n\n.field__label { display: block; font-size: 12.5px; font-weight: 680; margin-bottom: 7px; }\n.field__opt { font-weight: 560; color: var(--muted); }\n\n.field__control {\n  display: flex;\n  align-items: center;\n  gap: 9px;\n  background: #F4F8FD;\n  border: 1.5px solid transparent;\n  border-radius: 13px;\n  padding: 0 13px;\n  transition: border-color .16s ease, background .16s ease;\n}\n.field__control:focus-within { border-color: var(--blue-500); background: #fff; }\n.field.is-bad .field__control { border-color: var(--red); background: var(--red-bg); }\n\n.field__icon { color: var(--blue-600); width: 18px; height: 18px; }\n\n.field__control input {\n  flex: 1;\n  min-width: 0;\n  border: 0;\n  outline: 0;\n  background: none;\n  padding: 13px 0;\n  font-size: 14.5px;\n  font-weight: 600;\n}\n.field__control input::placeholder { color: #A9B9C9; font-weight: 540; }\n\n.field__error {\n  font-size: 11.5px;\n  font-weight: 640;\n  color: var(--red);\n  margin-top: 5px;\n  min-height: 0;\n}\n.field__hint {\n  font-size: 11px;\n  font-weight: 540;\n  color: var(--muted);\n  margin-top: 5px;\n  line-height: 1.45;\n}\n\n.searchbar {\n  display: flex;\n  align-items: center;\n  gap: 9px;\n  background: #fff;\n  border-radius: 13px;\n  padding: 0 13px;\n  margin-bottom: 12px;\n  flex: none;\n  box-shadow: 0 2px 8px rgba(11, 42, 74, .05);\n}\n.searchbar__icon { color: var(--muted); width: 18px; height: 18px; }\n.searchbar input {\n  flex: 1;\n  min-width: 0;\n  border: 0;\n  outline: 0;\n  background: none;\n  padding: 12px 0;\n  font-size: 14px;\n  font-weight: 600;\n}\n\n/* Native search clear button clashes with the card styling. */\n.searchbar input::-webkit-search-cancel-button { -webkit-appearance: none; }\n\n/* ----------------------------------------------------------- buttons */\n.btn {\n  border: 0;\n  border-radius: 14px;\n  padding: 14px 20px;\n  font-size: 14.5px;\n  font-weight: 700;\n  cursor: pointer;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 7px;\n  transition: transform .12s ease, opacity .16s ease;\n}\n.btn:active { transform: scale(.97); }\n.btn:disabled { opacity: .55; }\n\n.btn--primary {\n  background: linear-gradient(160deg, var(--blue-500), var(--blue-700));\n  color: #fff;\n  box-shadow: 0 6px 18px rgba(26, 115, 232, .3);\n}\n.btn--ghost { background: #EEF3FA; color: var(--navy-800); }\n.btn--soft { background: var(--blue-100); color: var(--blue-700); }\n.btn--block { width: 100%; }\n.btn--danger { background: var(--red-bg); color: var(--red); margin-top: 14px; }\n.btn--danger.btn--solid {\n  background: var(--red);\n  color: #fff;\n  margin-top: 0;\n  box-shadow: 0 6px 18px rgba(224, 59, 69, .3);\n}\n\n.sheet__actions { display: flex; gap: 10px; }\n.sheet__actions .btn { flex: 1; }\n\n.fab {\n  position: absolute;\n  left: 18px;\n  right: 18px;\n  bottom: 18px;\n  border: 0;\n  border-radius: 16px;\n  padding: 15px;\n  background: linear-gradient(160deg, var(--blue-500), var(--blue-700));\n  color: #fff;\n  font-size: 14.5px;\n  font-weight: 720;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  box-shadow: 0 10px 26px rgba(26, 115, 232, .34);\n  z-index: 5;\n}\n.fab:active { transform: scale(.98); }\n\n/* ------------------------------------------------------------ tabbar */\n.tabbar {\n  flex: none;\n  height: var(--tab-h);\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  align-items: start;\n  padding: 9px 6px 0;\n  background: rgba(255, 255, 255, .93);\n  backdrop-filter: blur(18px) saturate(180%);\n  -webkit-backdrop-filter: blur(18px) saturate(180%);\n  border-top: 1px solid var(--line);\n  position: relative;\n  z-index: 10;\n}\n.tab {\n  border: 0;\n  background: none;\n  cursor: pointer;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 4px;\n  padding: 6px 2px;\n  color: #93A3B6;\n  transition: color .2s ease, transform .14s ease;\n}\n.tab span { font-size: 10px; font-weight: 640; letter-spacing: .1px; }\n.tab:active { transform: scale(.92); }\n.tab.is-on { color: var(--blue-600); }\n.tab.is-on .icon { stroke-width: 2.1; }\n\n/* ------------------------------------------------------------ sheets */\n.scrim {\n  position: absolute;\n  inset: 0;\n  background: rgba(7, 27, 48, .48);\n  opacity: 0;\n  transition: opacity .28s ease;\n  z-index: 40;\n}\n.scrim.is-on { opacity: 1; }\n\n.sheet {\n  position: absolute;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  background: #fff;\n  border-radius: 26px 26px 0 0;\n  padding: 10px 20px 22px;\n  transform: translateY(102%);\n  transition: transform .34s cubic-bezier(.32, .72, 0, 1);\n  z-index: 50;\n  display: flex;\n  flex-direction: column;\n  gap: 14px;\n  max-height: 88%;\n}\n.sheet.is-open { transform: translateY(0); }\n.sheet--tall { max-height: 92%; }\n\n.sheet__grab {\n  width: 38px;\n  height: 4.5px;\n  border-radius: 3px;\n  background: #D5DFEA;\n  margin: 0 auto 6px;\n  flex: none;\n}\n.sheet__title { font-size: 19px; font-weight: 760; letter-spacing: -.4px; }\n\n.sheet form { display: flex; flex-direction: column; gap: 14px; min-height: 0; }\n.sheetscroll {\n  display: flex;\n  flex-direction: column;\n  gap: 15px;\n  overflow-y: auto;\n  min-height: 0;\n  padding-bottom: 2px;\n}\n\n.sheet__note {\n  font-size: 12px;\n  font-weight: 600;\n  line-height: 1.5;\n  padding: 11px 13px;\n  border-radius: 12px;\n  background: #F4F8FD;\n  color: var(--muted);\n}\n.sheet__note--info { background: var(--blue-100); color: var(--blue-700); }\n.sheet__note--warn { background: var(--amber-bg); color: var(--amber); }\n\n.setresult {\n  font-size: 12.5px;\n  font-weight: 620;\n  padding: 11px 13px;\n  border-radius: 12px;\n  line-height: 1.45;\n}\n.setresult--ok   { background: var(--green-bg); color: var(--green-2); }\n.setresult--bad  { background: var(--red-bg);   color: var(--red); }\n.setresult--busy { background: var(--blue-100); color: var(--blue-700); }\n\n/* ------------------------------------------------------------ switch */\n.switchrow {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 14px;\n  cursor: pointer;\n  padding: 4px 0;\n}\n.switchrow__label { font-size: 13px; font-weight: 620; line-height: 1.45; }\n.switchrow input { position: absolute; opacity: 0; pointer-events: none; }\n\n.switchrow__track {\n  flex: none;\n  width: 46px;\n  height: 28px;\n  border-radius: 999px;\n  background: #D5DFEA;\n  padding: 3px;\n  transition: background .2s ease;\n}\n.switchrow__knob {\n  display: block;\n  width: 22px;\n  height: 22px;\n  border-radius: 50%;\n  background: #fff;\n  box-shadow: 0 1px 4px rgba(7, 27, 48, .28);\n  transition: transform .2s cubic-bezier(.32, .72, 0, 1);\n}\n.switchrow input:checked ~ .switchrow__track { background: var(--green); }\n.switchrow input:checked ~ .switchrow__track .switchrow__knob { transform: translateX(18px); }\n\n/* ----------------------------------------------------------- sign in */\n.signin {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  gap: 22px;\n  padding: 10px 0 24px;\n}\n.signin__brand { text-align: center; display: flex; flex-direction: column; align-items: center; gap: 5px; }\n.signin__mark { width: 58px; height: 58px; color: var(--navy-800); }\n.signin__title { font-size: 26px; font-weight: 800; letter-spacing: -.8px; }\n.signin__role {\n  font-size: 11px;\n  font-weight: 760;\n  letter-spacing: 1.4px;\n  text-transform: uppercase;\n  color: var(--blue-600);\n}\n.signin__foot {\n  font-size: 11.5px;\n  font-weight: 540;\n  color: var(--muted);\n  text-align: center;\n  line-height: 1.55;\n}\n\n/* ------------------------------------------------------------- toast */\n.toast {\n  position: absolute;\n  left: 20px;\n  right: 20px;\n  bottom: calc(var(--tab-h) + 22px);\n  background: var(--navy-900);\n  color: #fff;\n  font-size: 13px;\n  font-weight: 620;\n  padding: 13px 16px;\n  border-radius: 14px;\n  text-align: center;\n  opacity: 0;\n  transform: translateY(14px);\n  transition: opacity .24s ease, transform .24s ease;\n  pointer-events: none;\n  z-index: 60;\n  line-height: 1.45;\n}\n.toast.is-on { opacity: 1; transform: translateY(0); }\n\n/* The tab bar is hidden while signed out, so the toast sits lower. */\n#tabs[hidden] ~ .toast { bottom: 26px; }\n\n</style>\n<script>\n  /* The native shell sets this before any document script runs, so the mock\n     status bar can be dropped before first paint. */\n  if (window.__PHARMACHECK_NATIVE__) document.documentElement.classList.add('is-native');\n</script>\n</head>\n<body>\n\n<!-- ============================ ICON SPRITE ============================ -->\n<svg class=\"sprite\" aria-hidden=\"true\" focusable=\"false\">\n  <symbol id=\"i-grid\" viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"3\" width=\"7.5\" height=\"7.5\" rx=\"2\"/><rect x=\"13.5\" y=\"3\" width=\"7.5\" height=\"7.5\" rx=\"2\"/><rect x=\"3\" y=\"13.5\" width=\"7.5\" height=\"7.5\" rx=\"2\"/><rect x=\"13.5\" y=\"13.5\" width=\"7.5\" height=\"7.5\" rx=\"2\"/></symbol>\n  <symbol id=\"i-shop\" viewBox=\"0 0 24 24\"><path d=\"M4 9h16v10a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V9Z\"/><path d=\"M3.5 9 5 4h14l1.5 5\"/><path d=\"M9.5 21v-6h5v6\"/></symbol>\n  <symbol id=\"i-users\" viewBox=\"0 0 24 24\"><circle cx=\"9\" cy=\"8\" r=\"3.4\"/><path d=\"M2.6 20a6.4 6.4 0 0 1 12.8 0\"/><path d=\"M16.5 5.2a3.4 3.4 0 0 1 0 6.6M17.5 14.4a6.4 6.4 0 0 1 3.9 5.6\"/></symbol>\n  <symbol id=\"i-cog\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"3.2\"/><path d=\"M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 1 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06A1.65 1.65 0 0 0 4.6 15a1.65 1.65 0 0 0-1.51-1H3a2 2 0 1 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06A1.65 1.65 0 0 0 9 4.6a1.65 1.65 0 0 0 1-1.51V3a2 2 0 1 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06A1.65 1.65 0 0 0 19.4 9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 1 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1Z\"/></symbol>\n  <symbol id=\"i-back\" viewBox=\"0 0 24 24\"><path d=\"M15 19l-7-7 7-7\"/></symbol>\n  <symbol id=\"i-chevron\" viewBox=\"0 0 24 24\"><path d=\"M9 6l6 6-6 6\"/></symbol>\n  <symbol id=\"i-plus\" viewBox=\"0 0 24 24\"><path d=\"M12 5v14M5 12h14\"/></symbol>\n  <symbol id=\"i-check\" viewBox=\"0 0 24 24\"><path d=\"M20 6 9 17l-5-5\"/></symbol>\n  <symbol id=\"i-key\" viewBox=\"0 0 24 24\"><circle cx=\"7.5\" cy=\"15.5\" r=\"4\"/><path d=\"m10.4 12.6 8.1-8.1M16 7l2.5 2.5M13.5 9.5 16 12\"/></symbol>\n  <symbol id=\"i-cloud\" viewBox=\"0 0 24 24\"><path d=\"M17.5 19H7a4.5 4.5 0 0 1-.6-8.96A6 6 0 0 1 17.9 9.2a4.4 4.4 0 0 1-.4 9.8Z\"/></symbol>\n  <symbol id=\"i-db\" viewBox=\"0 0 24 24\"><ellipse cx=\"12\" cy=\"5.5\" rx=\"7.5\" ry=\"3\"/><path d=\"M4.5 5.5v13c0 1.66 3.36 3 7.5 3s7.5-1.34 7.5-3v-13\"/><path d=\"M4.5 12c0 1.66 3.36 3 7.5 3s7.5-1.34 7.5-3\"/></symbol>\n  <symbol id=\"i-alert\" viewBox=\"0 0 24 24\"><path d=\"M12 3.8 2.6 20h18.8L12 3.8Z\"/><path d=\"M12 10v4.2M12 17.2v.2\"/></symbol>\n  <symbol id=\"i-logout\" viewBox=\"0 0 24 24\"><path d=\"M15 17v2a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h7a2 2 0 0 1 2 2v2\"/><path d=\"M10 12h11m-3-3 3 3-3 3\"/></symbol>\n  <symbol id=\"i-trash\" viewBox=\"0 0 24 24\"><path d=\"M4 7h16M9.5 7V5a1 1 0 0 1 1-1h3a1 1 0 0 1 1 1v2\"/><path d=\"M6.5 7 7.4 20a1 1 0 0 0 1 .9h7.2a1 1 0 0 0 1-.9L17.5 7\"/></symbol>\n  <symbol id=\"i-pen\" viewBox=\"0 0 24 24\"><path d=\"M4 20h4L20 8a2.8 2.8 0 0 0-4-4L4 16v4Z\"/><path d=\"m14.5 5.5 4 4\"/></symbol>\n  <symbol id=\"i-search\" viewBox=\"0 0 24 24\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m20 20-3.5-3.5\"/></symbol>\n  <symbol id=\"i-refresh\" viewBox=\"0 0 24 24\"><path d=\"M20.5 12a8.5 8.5 0 1 1-2.6-6.1\"/><path d=\"M20.5 4.5V10h-5.5\"/></symbol>\n</svg>\n\n<div class=\"stage\">\n  <div class=\"phone\" id=\"phone\">\n\n    <!-- Simulated status bar; hidden inside the native shell -->\n    <div class=\"statusbar\" aria-hidden=\"true\">\n      <span class=\"sb-time\" id=\"sb-time\">9:41</span>\n      <span class=\"sb-right\">\n        <svg viewBox=\"0 0 20 12\" class=\"sb-signal\"><rect x=\"0\" y=\"8\" width=\"3\" height=\"4\" rx=\"1\"/><rect x=\"4.5\" y=\"5.5\" width=\"3\" height=\"6.5\" rx=\"1\"/><rect x=\"9\" y=\"3\" width=\"3\" height=\"9\" rx=\"1\"/><rect x=\"13.5\" y=\"0\" width=\"3\" height=\"12\" rx=\"1\"/></svg>\n        <svg viewBox=\"0 0 26 12\" class=\"sb-batt\"><rect x=\"0.6\" y=\"0.6\" width=\"21\" height=\"10.8\" rx=\"3.2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.2\" opacity=\".45\"/><rect x=\"2.4\" y=\"2.4\" width=\"15\" height=\"7.2\" rx=\"2\"/><path d=\"M23.4 4.2v3.6a2.2 2.2 0 0 0 0-3.6Z\" opacity=\".45\"/></svg>\n      </span>\n    </div>\n\n    <main class=\"viewport\" id=\"viewport\">\n\n      <!-- ===================== 0. SIGN IN ===================== -->\n      <section class=\"screen screen--scroll is-active\" id=\"screen-signin\" aria-label=\"Sign in\">\n        <div class=\"signin\">\n          <div class=\"signin__brand\">\n            <svg viewBox=\"0 0 100 100\" class=\"signin__mark\" aria-hidden=\"true\">\n              <path d=\"M26 18h27a17.5 17.5 0 0 1 0 35H40v29H26z\" fill=\"currentColor\"/>\n              <g stroke=\"currentColor\" stroke-width=\"10\" stroke-linecap=\"round\">\n                <line x1=\"52\" y1=\"55\" x2=\"80\" y2=\"85\"/><line x1=\"52\" y1=\"85\" x2=\"80\" y2=\"55\"/>\n              </g>\n            </svg>\n            <h1 class=\"signin__title\">PharmaCheck</h1>\n            <p class=\"signin__role\">Super Admin</p>\n          </div>\n\n          <div class=\"card setform\">\n            <div class=\"field\">\n              <label class=\"field__label\" for=\"si-url\">Worker URL</label>\n              <div class=\"field__control\">\n                <svg class=\"icon field__icon\"><use href=\"#i-cloud\"/></svg>\n                <input id=\"si-url\" type=\"url\" inputmode=\"url\" autocomplete=\"off\" spellcheck=\"false\"\n                       placeholder=\"https://pharmacheck-sync.you.workers.dev\">\n              </div>\n              <p class=\"field__hint\">The address <code>wrangler deploy</code> printed.</p>\n            </div>\n\n            <div class=\"field\">\n              <label class=\"field__label\" for=\"si-key\">Setup key</label>\n              <div class=\"field__control\">\n                <svg class=\"icon field__icon\"><use href=\"#i-key\"/></svg>\n                <input id=\"si-key\" type=\"password\" autocomplete=\"off\" placeholder=\"your SETUP_KEY\">\n              </div>\n              <p class=\"field__hint\">Never saved on this phone. It is exchanged for a session that lasts 8 hours.</p>\n            </div>\n\n            <button class=\"btn btn--primary btn--block\" type=\"button\" id=\"si-go\">Sign in</button>\n            <p class=\"setresult\" id=\"si-result\" hidden></p>\n          </div>\n\n          <p class=\"signin__foot\" id=\"si-foot\">Not set up yet? Deploy the Worker first — see <code>worker/README.md</code>.</p>\n        </div>\n      </section>\n\n      <!-- ===================== 1. DASHBOARD ===================== -->\n      <section class=\"screen screen--scroll\" id=\"screen-dashboard\" aria-label=\"Dashboard\">\n        <header class=\"apphead\">\n          <div>\n            <p class=\"apphead__date\" id=\"dash-date\">—</p>\n            <h1 class=\"apphead__title\">Overview</h1>\n            <p class=\"apphead__sub\" id=\"dash-sub\">—</p>\n          </div>\n          <div class=\"apphead__actions\">\n            <button class=\"iconbtn iconbtn--ghost\" type=\"button\" id=\"dash-refresh\" aria-label=\"Refresh\">\n              <svg class=\"icon\"><use href=\"#i-refresh\"/></svg>\n            </button>\n          </div>\n        </header>\n\n        <div class=\"statgrid\">\n          <div class=\"card stat\">\n            <p class=\"stat__label\">Pharmacies</p>\n            <p class=\"stat__value\" id=\"ov-pharmacies\">—</p>\n          </div>\n          <div class=\"card stat\">\n            <p class=\"stat__label\">Accounts</p>\n            <p class=\"stat__value\" id=\"ov-accounts\">—</p>\n            <p class=\"stat__meta\" id=\"ov-vendors\">—</p>\n          </div>\n          <div class=\"card stat\">\n            <p class=\"stat__label\">Medicines</p>\n            <p class=\"stat__value\" id=\"ov-medicines\">—</p>\n          </div>\n          <div class=\"card stat\">\n            <p class=\"stat__label\">Sales logged</p>\n            <p class=\"stat__value\" id=\"ov-sales\">—</p>\n            <p class=\"stat__meta\" id=\"ov-revenue\">—</p>\n          </div>\n        </div>\n\n        <div class=\"section-head\">\n          <h2 class=\"section-title\">Pharmacies</h2>\n          <button class=\"linkbtn\" type=\"button\" data-go=\"pharmacies\">Manage <svg class=\"icon icon--xs\"><use href=\"#i-chevron\"/></svg></button>\n        </div>\n        <ul class=\"cardlist\" id=\"ov-list\"></ul>\n      </section>\n\n      <!-- ===================== 2. PHARMACIES ===================== -->\n      <section class=\"screen screen--fixed\" id=\"screen-pharmacies\" aria-label=\"Pharmacies\">\n        <header class=\"apphead apphead--compact\">\n          <div>\n            <h1 class=\"apphead__title apphead__title--sm\">Pharmacies</h1>\n            <p class=\"apphead__sub\" id=\"ph-sub\">—</p>\n          </div>\n        </header>\n\n        <div class=\"searchbar\">\n          <svg class=\"icon searchbar__icon\"><use href=\"#i-search\"/></svg>\n          <input id=\"ph-search\" type=\"search\" placeholder=\"Search by code\" autocomplete=\"off\">\n        </div>\n\n        <ul class=\"cardlist cardlist--scroll\" id=\"ph-list\"></ul>\n\n        <button class=\"fab fab--wide\" type=\"button\" id=\"ph-add\">\n          <svg class=\"icon\"><use href=\"#i-plus\"/></svg> New pharmacy\n        </button>\n      </section>\n\n      <!-- ===================== 3. PHARMACY DETAIL ===================== -->\n      <section class=\"screen screen--scroll\" id=\"screen-detail\" aria-label=\"Pharmacy\">\n        <header class=\"apphead apphead--compact\">\n          <button class=\"iconbtn iconbtn--ghost\" type=\"button\" data-go=\"pharmacies\" aria-label=\"Back\">\n            <svg class=\"icon\"><use href=\"#i-back\"/></svg>\n          </button>\n          <div>\n            <h1 class=\"apphead__title apphead__title--sm\" id=\"dt-code\">—</h1>\n            <p class=\"apphead__sub\" id=\"dt-sub\">—</p>\n          </div>\n        </header>\n\n        <div class=\"card dbcard\">\n          <svg class=\"icon dbcard__icon\"><use href=\"#i-db\"/></svg>\n          <div class=\"dbcard__body\">\n            <p class=\"dbcard__name\" id=\"dt-db\">—</p>\n            <p class=\"dbcard__meta\" id=\"dt-created\">—</p>\n          </div>\n        </div>\n\n        <div class=\"statgrid statgrid--tight\">\n          <div class=\"card stat\">\n            <p class=\"stat__label\">Medicines</p>\n            <p class=\"stat__value\" id=\"dt-medicines\">—</p>\n            <p class=\"stat__meta\" id=\"dt-units\">—</p>\n          </div>\n          <div class=\"card stat\">\n            <p class=\"stat__label\">Sales</p>\n            <p class=\"stat__value\" id=\"dt-sales\">—</p>\n            <p class=\"stat__meta\" id=\"dt-revenue\">—</p>\n          </div>\n        </div>\n\n        <div class=\"section-head\">\n          <h2 class=\"section-title\">Manager</h2>\n          <button class=\"linkbtn\" type=\"button\" data-add-role=\"manager\">Add</button>\n        </div>\n        <ul class=\"cardlist\" id=\"dt-managers\"></ul>\n\n        <div class=\"section-head\">\n          <h2 class=\"section-title\">Vendors</h2>\n          <button class=\"linkbtn\" type=\"button\" data-add-role=\"vendor\">Add</button>\n        </div>\n        <ul class=\"cardlist\" id=\"dt-vendors\"></ul>\n\n        <div class=\"section-head\"><h2 class=\"section-title\">Set up a phone</h2></div>\n        <div class=\"card connectcard\">\n          <p class=\"connectcard__note\">Enter these two on the phone, in the pharmacy app's Connect screen.</p>\n          <dl class=\"kv\">\n            <div class=\"kv__row\"><dt>Worker URL</dt><dd id=\"dt-url\">—</dd></div>\n            <div class=\"kv__row\"><dt>Pharmacy code</dt><dd id=\"dt-copycode\">—</dd></div>\n          </dl>\n        </div>\n\n        <button class=\"btn btn--danger btn--block\" type=\"button\" id=\"dt-archive\">Archive this pharmacy</button>\n      </section>\n\n      <!-- ===================== 4. SETTINGS ===================== -->\n      <section class=\"screen screen--scroll\" id=\"screen-settings\" aria-label=\"Settings\">\n        <header class=\"apphead apphead--compact\">\n          <div>\n            <h1 class=\"apphead__title apphead__title--sm\">Settings</h1>\n            <p class=\"apphead__sub\">What this admin app is connected to</p>\n          </div>\n        </header>\n\n        <!-- Step 1 -->\n        <div class=\"steprow\"><span class=\"stepnum\">1</span><h2 class=\"section-title\">The Worker</h2></div>\n        <div class=\"card setform\">\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"st-url\">Worker URL</label>\n            <div class=\"field__control\">\n              <svg class=\"icon field__icon\"><use href=\"#i-cloud\"/></svg>\n              <input id=\"st-url\" type=\"url\" inputmode=\"url\" autocomplete=\"off\" spellcheck=\"false\"\n                     placeholder=\"https://pharmacheck-sync.you.workers.dev\">\n            </div>\n          </div>\n          <div class=\"sheet__actions\">\n            <button class=\"btn btn--ghost\" type=\"button\" id=\"st-check\">Check</button>\n            <button class=\"btn btn--primary\" type=\"button\" id=\"st-save-url\">Save</button>\n          </div>\n          <p class=\"setresult\" id=\"st-url-result\" hidden></p>\n        </div>\n\n        <!-- Step 2 -->\n        <div class=\"steprow\"><span class=\"stepnum\">2</span><h2 class=\"section-title\">Turso database</h2></div>\n        <div class=\"card setform\">\n          <p class=\"sheet__note sheet__note--info\" id=\"st-source\">—</p>\n\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"st-org\">Organisation</label>\n            <div class=\"field__control\">\n              <svg class=\"icon field__icon\"><use href=\"#i-db\"/></svg>\n              <input id=\"st-org\" type=\"text\" autocomplete=\"off\" spellcheck=\"false\" placeholder=\"your-org\">\n            </div>\n            <p class=\"field__hint\">From your Turso dashboard URL, or <code>turso org list</code>.</p>\n          </div>\n\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"st-group\">Group</label>\n            <div class=\"field__control\">\n              <svg class=\"icon field__icon\"><use href=\"#i-db\"/></svg>\n              <input id=\"st-group\" type=\"text\" autocomplete=\"off\" spellcheck=\"false\" placeholder=\"default\">\n            </div>\n            <p class=\"field__hint\">Where new pharmacy databases are created. It must already exist.</p>\n          </div>\n\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"st-token\">Platform token</label>\n            <div class=\"field__control\">\n              <svg class=\"icon field__icon\"><use href=\"#i-key\"/></svg>\n              <input id=\"st-token\" type=\"password\" autocomplete=\"off\" spellcheck=\"false\" placeholder=\"leave blank to keep the current one\">\n            </div>\n            <p class=\"field__hint\"><code>turso auth api-tokens mint pharmacheck</code></p>\n          </div>\n\n          <p class=\"sheet__note sheet__note--warn\">\n            This token can create and destroy every database you own. Saved here it is\n            kept by the Worker, not by this phone — but it does cross this handset once.\n            <code>wrangler secret put TURSO_PLATFORM_TOKEN</code> avoids that, and takes priority.\n          </p>\n\n          <div class=\"sheet__actions\">\n            <button class=\"btn btn--ghost\" type=\"button\" id=\"st-test\">Test</button>\n            <button class=\"btn btn--primary\" type=\"button\" id=\"st-save-turso\">Save</button>\n          </div>\n          <p class=\"setresult\" id=\"st-turso-result\" hidden></p>\n        </div>\n\n        <!-- Step 3 -->\n        <div class=\"steprow\"><span class=\"stepnum\">3</span><h2 class=\"section-title\">Worker secrets</h2></div>\n        <ul class=\"card checklist\" id=\"st-checklist\"></ul>\n\n        <button class=\"btn btn--danger btn--block\" type=\"button\" id=\"st-signout\">\n          <svg class=\"icon icon--xs\"><use href=\"#i-logout\"/></svg> Sign out\n        </button>\n      </section>\n\n    </main>\n\n    <!-- ============================ TAB BAR ============================ -->\n    <nav class=\"tabbar\" id=\"tabs\" aria-label=\"Primary\" hidden>\n      <button class=\"tab is-on\" type=\"button\" data-go=\"dashboard\" aria-current=\"page\">\n        <svg class=\"icon\"><use href=\"#i-grid\"/></svg><span>Overview</span>\n      </button>\n      <button class=\"tab\" type=\"button\" data-go=\"pharmacies\">\n        <svg class=\"icon\"><use href=\"#i-shop\"/></svg><span>Pharmacies</span>\n      </button>\n      <button class=\"tab\" type=\"button\" data-go=\"settings\">\n        <svg class=\"icon\"><use href=\"#i-cog\"/></svg><span>Settings</span>\n      </button>\n    </nav>\n\n    <div class=\"homebar\" aria-hidden=\"true\"></div>\n\n    <!-- ===================== NEW PHARMACY SHEET ===================== -->\n    <div class=\"scrim\" id=\"scrim\" hidden></div>\n    <div class=\"sheet sheet--modal sheet--tall\" id=\"new-sheet\" aria-hidden=\"true\" role=\"dialog\" aria-label=\"New pharmacy\">\n      <div class=\"sheet__grab\"></div>\n      <h2 class=\"sheet__title\">New pharmacy</h2>\n      <form id=\"new-form\" novalidate>\n        <div class=\"sheetscroll\">\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"np-code\">Pharmacy code</label>\n            <div class=\"field__control\">\n              <input id=\"np-code\" name=\"code\" type=\"text\" autocomplete=\"off\" spellcheck=\"false\" placeholder=\"central\">\n            </div>\n            <p class=\"field__error\" data-error-for=\"code\"></p>\n            <p class=\"field__hint\">Lowercase letters, digits and dashes. Each phone types this once.</p>\n          </div>\n\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"np-label\">Display name <span class=\"field__opt\">optional</span></label>\n            <div class=\"field__control\">\n              <input id=\"np-label\" name=\"label\" type=\"text\" autocomplete=\"off\" placeholder=\"Pharmacie Centrale, Alger\">\n            </div>\n          </div>\n\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"np-manager\">Manager name</label>\n            <div class=\"field__control\">\n              <svg class=\"icon field__icon\"><use href=\"#i-users\"/></svg>\n              <input id=\"np-manager\" name=\"managerName\" type=\"text\" autocomplete=\"off\" placeholder=\"Sarah Kaur\">\n            </div>\n            <p class=\"field__error\" data-error-for=\"managerName\"></p>\n          </div>\n\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"np-pin\">Manager PIN</label>\n            <div class=\"field__control\">\n              <input id=\"np-pin\" name=\"managerPin\" type=\"text\" inputmode=\"numeric\" maxlength=\"4\" autocomplete=\"off\" placeholder=\"4 digits\">\n            </div>\n            <p class=\"field__error\" data-error-for=\"managerPin\"></p>\n            <p class=\"field__hint\">Give this to the manager. They can change it later.</p>\n          </div>\n\n          <p class=\"sheet__note sheet__note--info\">\n            Creates a Turso database for this pharmacy and writes the manager account.\n            It takes a few seconds.\n          </p>\n          <p class=\"setresult\" id=\"np-result\" hidden></p>\n        </div>\n\n        <div class=\"sheet__actions\">\n          <button class=\"btn btn--ghost\" type=\"button\" id=\"np-cancel\">Cancel</button>\n          <button class=\"btn btn--primary\" type=\"submit\" id=\"np-save\">Create</button>\n        </div>\n      </form>\n    </div>\n\n    <!-- ===================== ACCOUNT SHEET ===================== -->\n    <div class=\"sheet sheet--modal\" id=\"acct-sheet\" aria-hidden=\"true\" role=\"dialog\" aria-label=\"Account\">\n      <div class=\"sheet__grab\"></div>\n      <h2 class=\"sheet__title\" id=\"ac-title\">Add vendor</h2>\n      <form id=\"acct-form\" novalidate>\n        <div class=\"field\">\n          <label class=\"field__label\" for=\"ac-name\">Name</label>\n          <div class=\"field__control\">\n            <svg class=\"icon field__icon\"><use href=\"#i-users\"/></svg>\n            <input id=\"ac-name\" name=\"name\" type=\"text\" autocomplete=\"off\" placeholder=\"Karim Toumi\">\n          </div>\n          <p class=\"field__error\" data-error-for=\"name\"></p>\n        </div>\n\n        <div class=\"field\">\n          <label class=\"field__label\" for=\"ac-pin\"><span id=\"ac-pin-label\">4-digit PIN</span></label>\n          <div class=\"field__control\">\n            <input id=\"ac-pin\" name=\"pin\" type=\"text\" inputmode=\"numeric\" maxlength=\"4\" autocomplete=\"off\" placeholder=\"1234\">\n          </div>\n          <p class=\"field__error\" data-error-for=\"pin\"></p>\n        </div>\n\n        <label class=\"switchrow\" id=\"ac-active-row\">\n          <span class=\"switchrow__label\">Can sign in</span>\n          <input id=\"ac-active\" type=\"checkbox\" checked>\n          <span class=\"switchrow__track\"><span class=\"switchrow__knob\"></span></span>\n        </label>\n\n        <p class=\"setresult\" id=\"ac-result\" hidden></p>\n\n        <div class=\"sheet__actions\">\n          <button class=\"btn btn--ghost\" type=\"button\" id=\"ac-cancel\">Cancel</button>\n          <button class=\"btn btn--primary\" type=\"submit\" id=\"ac-save\">Save</button>\n        </div>\n        <button class=\"btn btn--danger btn--block\" type=\"button\" id=\"ac-remove\" hidden>Remove this account</button>\n      </form>\n    </div>\n\n    <!-- ===================== CONFIRM SHEET ===================== -->\n    <div class=\"sheet sheet--modal\" id=\"confirm-sheet\" aria-hidden=\"true\" role=\"dialog\" aria-label=\"Confirm\">\n      <div class=\"sheet__grab\"></div>\n      <h2 class=\"sheet__title\" id=\"cf-title\">Are you sure?</h2>\n      <p class=\"sheet__note sheet__note--warn\" id=\"cf-body\">—</p>\n\n      <label class=\"switchrow\" id=\"cf-drop-row\">\n        <span class=\"switchrow__label\">Also delete the database and all its records</span>\n        <input id=\"cf-drop\" type=\"checkbox\">\n        <span class=\"switchrow__track\"><span class=\"switchrow__knob\"></span></span>\n      </label>\n\n      <div class=\"field\" id=\"cf-typebox\">\n        <label class=\"field__label\" for=\"cf-type\">Type the pharmacy code to confirm</label>\n        <div class=\"field__control\">\n          <input id=\"cf-type\" type=\"text\" autocomplete=\"off\" spellcheck=\"false\" placeholder=\"\">\n        </div>\n      </div>\n\n      <p class=\"setresult\" id=\"cf-result\" hidden></p>\n\n      <div class=\"sheet__actions\">\n        <button class=\"btn btn--ghost\" type=\"button\" id=\"cf-cancel\">Cancel</button>\n        <button class=\"btn btn--danger btn--solid\" type=\"button\" id=\"cf-go\">Archive</button>\n      </div>\n    </div>\n\n    <div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n  </div>\n</div>\n\n<script>\n/* =====================================================================\n   PharmaCheck Admin — the client for the Worker's admin API.\n\n   Two things are stored on this device and nothing else is: the Worker\n   URL, and the session token minted when the setup key was accepted.\n\n   The setup key itself is never written down. It is typed at sign-in,\n   exchanged for a token that expires in 8 hours, and forgotten — so a\n   lost handset costs one working day of access, not the key that can\n   create and destroy every database in the organisation.\n   ===================================================================== */\n(function (global) {\n  'use strict';\n\n  var KEY = 'pharmacheck.admin.v1';\n  var TIMEOUT = 25000;\n\n  var cfg = null;\n\n  function defaults() {\n    return { workerUrl: '', token: null, tokenExp: 0, lastError: null };\n  }\n\n  function config() {\n    if (cfg) return cfg;\n    try {\n      var raw = global.localStorage && global.localStorage.getItem(KEY);\n      cfg = raw ? Object.assign(defaults(), JSON.parse(raw)) : defaults();\n    } catch (e) {\n      cfg = defaults();\n    }\n    return cfg;\n  }\n\n  function persist() {\n    try {\n      if (global.localStorage) global.localStorage.setItem(KEY, JSON.stringify(cfg));\n    } catch (e) { /* private mode — settings just will not survive a restart */ }\n  }\n\n  function configure(patch) {\n    config();\n    Object.keys(patch || {}).forEach(function (k) { cfg[k] = patch[k]; });\n    if (cfg.workerUrl) cfg.workerUrl = String(cfg.workerUrl).trim().replace(/\\/+$/, '');\n    persist();\n    return cfg;\n  }\n\n  function signedIn() {\n    var c = config();\n    return Boolean(c.token && c.tokenExp > Date.now());\n  }\n\n  /* ------------------------------------------------------------------ *\n   * HTTP\n   * ------------------------------------------------------------------ */\n  function request(url, opts) {\n    var o = opts || {};\n    var controller = typeof AbortController !== 'undefined' ? new AbortController() : null;\n    var timer = setTimeout(function () { if (controller) controller.abort(); }, o.timeout || TIMEOUT);\n    var done = function (v) { clearTimeout(timer); return v; };\n\n    return fetch(url, {\n      method: o.method || 'GET',\n      headers: o.headers || {},\n      body: o.body,\n      signal: controller ? controller.signal : undefined\n    }).then(function (res) {\n      return res.text().then(function (text) {\n        var body = null;\n        try { body = text ? JSON.parse(text) : null; } catch (e) { /* not JSON */ }\n        if (!res.ok) {\n          var err = new Error((body && body.message) || text.slice(0, 200) || ('Server returned ' + res.status));\n          err.status = res.status;\n          throw err;\n        }\n        return done(body);\n      });\n    }, function (e) {\n      done();\n      if (e.name === 'AbortError') throw new Error('The Worker did not answer in time');\n      if (e instanceof TypeError) throw new Error('Could not reach the Worker — check the URL and the connection');\n      throw e;\n    }).catch(function (e) { done(); throw e; });\n  }\n\n  /* A 401 anywhere means the session is over, so the token is dropped at\n     the point of failure rather than leaving the app to discover it screen\n     by screen. */\n  function call(path, opts) {\n    var c = config();\n    if (!c.workerUrl) return Promise.reject(new Error('Set the Worker URL in Settings first'));\n\n    var o = opts || {};\n    var headers = { 'content-type': 'application/json' };\n    if (o.auth !== false && c.token) headers.authorization = 'Bearer ' + c.token;\n\n    return request(c.workerUrl + path, {\n      method: o.method || 'GET',\n      headers: headers,\n      body: o.body !== undefined ? JSON.stringify(o.body) : undefined,\n      timeout: o.timeout\n    }).catch(function (e) {\n      if (e.status === 401 && o.auth !== false) {\n        configure({ token: null, tokenExp: 0 });\n        e.signedOut = true;\n      }\n      throw e;\n    });\n  }\n\n  /* ------------------------------------------------------------------ *\n   * Session\n   * ------------------------------------------------------------------ */\n  function health(url) {\n    var target = (url || config().workerUrl || '').trim().replace(/\\/+$/, '');\n    if (!target) return Promise.reject(new Error('Enter the Worker URL first'));\n    return request(target + '/v1/health', { timeout: 12000 });\n  }\n\n  function signIn(workerUrl, setupKey) {\n    configure({ workerUrl: workerUrl });\n    return call('/v1/admin/signin', {\n      method: 'POST', auth: false, body: { setupKey: setupKey }\n    }).then(function (body) {\n      configure({ token: body.token, tokenExp: body.expiresAt, lastError: null });\n      return { ok: true, expiresAt: body.expiresAt };\n    });\n  }\n\n  function signOut() { configure({ token: null, tokenExp: 0 }); }\n\n  /* ------------------------------------------------------------------ *\n   * Turso configuration\n   * ------------------------------------------------------------------ */\n  function getConfig() {\n    return call('/v1/admin/config').then(function (b) { return b.config; });\n  }\n\n  function putConfig(fields) {\n    return call('/v1/admin/config', { method: 'PUT', body: fields })\n      .then(function (b) { return b.config; });\n  }\n\n  // Creating a database can take a while, so does confirming we could.\n  function testTurso() {\n    return call('/v1/admin/config/test', { timeout: 40000 });\n  }\n\n  /* ------------------------------------------------------------------ *\n   * Pharmacies and accounts\n   * ------------------------------------------------------------------ */\n  function overview() { return call('/v1/admin/overview', { timeout: 45000 }); }\n\n  function pharmacies() {\n    return call('/v1/admin/pharmacies').then(function (b) { return b.pharmacies || []; });\n  }\n\n  function pharmacy(code) {\n    return call('/v1/admin/pharmacies/' + encodeURIComponent(code));\n  }\n\n  function createPharmacy(fields) {\n    return call('/v1/admin/pharmacies', { method: 'POST', body: fields, timeout: 60000 });\n  }\n\n  function archivePharmacy(code, dropDatabase) {\n    return call('/v1/admin/pharmacies/' + encodeURIComponent(code), {\n      method: 'DELETE', body: { dropDatabase: Boolean(dropDatabase) }, timeout: 45000\n    });\n  }\n\n  function createAccount(code, fields) {\n    return call('/v1/admin/pharmacies/' + encodeURIComponent(code) + '/accounts', {\n      method: 'POST', body: fields\n    });\n  }\n\n  function updateAccount(code, id, fields) {\n    return call('/v1/admin/pharmacies/' + encodeURIComponent(code) + '/accounts/' + encodeURIComponent(id), {\n      method: 'PATCH', body: fields\n    });\n  }\n\n  function removeAccount(code, id) {\n    return call('/v1/admin/pharmacies/' + encodeURIComponent(code) + '/accounts/' + encodeURIComponent(id), {\n      method: 'DELETE', body: {}\n    });\n  }\n\n  global.AdminApi = {\n    config: config, configure: configure, signedIn: signedIn,\n    health: health, signIn: signIn, signOut: signOut,\n    getConfig: getConfig, putConfig: putConfig, testTurso: testTurso,\n    overview: overview, pharmacies: pharmacies, pharmacy: pharmacy,\n    createPharmacy: createPharmacy, archivePharmacy: archivePharmacy,\n    createAccount: createAccount, updateAccount: updateAccount, removeAccount: removeAccount\n  };\n})(typeof self !== 'undefined' ? self : this);\n\n</script>\n<script>\n/* =====================================================================\n   PharmaCheck Admin — application logic\n\n   Four screens above any single pharmacy: an overview of the estate, the\n   list of pharmacies, one pharmacy's accounts, and the settings that say\n   what this app is connected to.\n\n   Everything here goes through AdminApi, which holds a session minted\n   from the setup key. Nothing is cached across sign-ins — each screen\n   asks the Worker, because the Worker is the only thing that knows.\n   ===================================================================== */\n(function () {\n  'use strict';\n\n  var $ = function (sel, root) { return (root || document).querySelector(sel); };\n  var $$ = function (sel, root) {\n    return Array.prototype.slice.call((root || document).querySelectorAll(sel));\n  };\n\n  var Api = window.AdminApi;\n  var isNative = Boolean(window.__PHARMACHECK_NATIVE__ || window.ReactNativeWebView);\n  if (isNative) document.documentElement.classList.add('is-native');\n\n  function postToNative(message) {\n    if (window.ReactNativeWebView) {\n      window.ReactNativeWebView.postMessage(JSON.stringify(message));\n    }\n  }\n\n  /* ------------------------------------------------------------------ *\n   * Helpers\n   * ------------------------------------------------------------------ */\n  function escapeHtml(value) {\n    return String(value == null ? '' : value)\n      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')\n      .replace(/\"/g, '&quot;').replace(/'/g, '&#39;');\n  }\n\n  function money(value) {\n    var n = Number(value) || 0;\n    if (n >= 1000000) return (n / 1000000).toFixed(1).replace(/\\.0$/, '') + 'M DA';\n    if (n >= 1000) return (n / 1000).toFixed(1).replace(/\\.0$/, '') + 'k DA';\n    return Math.round(n) + ' DA';\n  }\n\n  function plural(n, one, many) {\n    return n + ' ' + (Number(n) === 1 ? one : (many || one + 's'));\n  }\n\n  function ago(ts) {\n    if (!ts) return 'never';\n    var secs = Math.max(0, Math.round((Date.now() - ts) / 1000));\n    if (secs < 60) return 'just now';\n    if (secs < 5400) return Math.round(secs / 60) + ' min ago';\n    if (secs < 172800) return Math.round(secs / 3600) + ' h ago';\n    return new Date(ts).toLocaleDateString([], { day: 'numeric', month: 'short', year: 'numeric' });\n  }\n\n  function initials(name) {\n    return String(name || '?').split(/\\s+/).map(function (w) { return w[0]; })\n      .join('').slice(0, 2).toUpperCase();\n  }\n\n  var toastTimer = null;\n  function toast(message) {\n    var el = $('#toast');\n    el.textContent = message;\n    el.classList.add('is-on');\n    clearTimeout(toastTimer);\n    toastTimer = setTimeout(function () { el.classList.remove('is-on'); }, 3200);\n  }\n\n  function result(sel, text, kind) {\n    var node = $(sel);\n    if (!text) { node.hidden = true; return; }\n    node.hidden = false;\n    node.textContent = text;\n    node.className = 'setresult setresult--' + (kind || 'ok');\n  }\n\n  function tickClock() {\n    var now = new Date();\n    $('#sb-time').textContent = now.getHours() + ':' + String(now.getMinutes()).padStart(2, '0');\n  }\n  tickClock();\n  setInterval(tickClock, 20000);\n\n  /* A signed-out session is not an error to report on five screens — it\n     is a single trip back to sign-in. */\n  function handle(e) {\n    if (e && e.signedOut) {\n      go('signin');\n      toast('That session expired — sign in again');\n      return true;\n    }\n    return false;\n  }\n\n  /* ------------------------------------------------------------------ *\n   * Routing\n   * ------------------------------------------------------------------ */\n  var SCREENS = ['signin', 'dashboard', 'pharmacies', 'detail', 'settings'];\n  var TAB_FOR_SCREEN = { dashboard: 'dashboard', pharmacies: 'pharmacies', detail: 'pharmacies', settings: 'settings' };\n\n  var current = 'signin';\n  var currentPharmacy = null;\n\n  function go(name) {\n    if (SCREENS.indexOf(name) === -1 || !$('#screen-' + name)) return;\n\n    // Everything but sign-in needs a session.\n    if (name !== 'signin' && !Api.signedIn()) name = 'signin';\n\n    $$('.screen').forEach(function (s) { s.classList.remove('is-active'); });\n    $('#screen-' + name).classList.add('is-active');\n\n    $('#tabs').hidden = name === 'signin';\n    var owner = TAB_FOR_SCREEN[name];\n    $$('.tab').forEach(function (t) {\n      var on = t.dataset.go === owner;\n      t.classList.toggle('is-on', on);\n      if (on) t.setAttribute('aria-current', 'page');\n      else t.removeAttribute('aria-current');\n    });\n\n    if (name === 'signin') renderSignIn();\n    if (name === 'dashboard') renderDashboard();\n    if (name === 'pharmacies') renderPharmacies();\n    if (name === 'detail') renderDetail();\n    if (name === 'settings') renderSettings();\n\n    var screen = $('#screen-' + name);\n    if (screen.classList.contains('screen--scroll')) screen.scrollTop = 0;\n\n    current = name;\n    postToNative({ type: 'screen', name: name });\n  }\n\n  window.__pharmaadminBack = function () {\n    if (anySheetOpen()) { closeSheets(); return; }\n    if (current === 'detail') { go('pharmacies'); return; }\n    if (current !== 'dashboard' && current !== 'signin') { go('dashboard'); return; }\n  };\n\n  document.addEventListener('click', function (event) {\n    var trigger = event.target.closest('[data-go]');\n    if (trigger) go(trigger.dataset.go);\n  });\n\n  /* ------------------------------------------------------------------ *\n   * Sheets\n   * ------------------------------------------------------------------ */\n  var scrim = $('#scrim');\n  var sheets = { newPharmacy: $('#new-sheet'), account: $('#acct-sheet'), confirm: $('#confirm-sheet') };\n\n  function anySheetOpen() {\n    return Object.keys(sheets).some(function (k) { return sheets[k].classList.contains('is-open'); });\n  }\n\n  function openSheet(sheet) {\n    scrim.hidden = false;\n    requestAnimationFrame(function () { scrim.classList.add('is-on'); });\n    sheet.classList.add('is-open');\n    sheet.setAttribute('aria-hidden', 'false');\n  }\n\n  function closeSheets() {\n    scrim.classList.remove('is-on');\n    Object.keys(sheets).forEach(function (k) {\n      sheets[k].classList.remove('is-open');\n      sheets[k].setAttribute('aria-hidden', 'true');\n    });\n    setTimeout(function () { if (!anySheetOpen()) scrim.hidden = true; }, 320);\n  }\n\n  scrim.addEventListener('click', closeSheets);\n\n  function markBad(input, message) {\n    var field = input.closest('.field');\n    if (field) {\n      field.classList.add('is-bad');\n      var err = field.querySelector('.field__error');\n      if (err) err.textContent = message;\n    }\n    input.focus({ preventScroll: true });\n  }\n\n  function clearBad(form) {\n    $$('.field', form).forEach(function (f) {\n      f.classList.remove('is-bad');\n      var err = f.querySelector('.field__error');\n      if (err) err.textContent = '';\n    });\n  }\n\n  /* ------------------------------------------------------------------ *\n   * 0. Sign in\n   * ------------------------------------------------------------------ */\n  function renderSignIn() {\n    var c = Api.config();\n    $('#si-url').value = c.workerUrl || '';\n    result('#si-result', '');\n  }\n\n  $('#si-go').addEventListener('click', function () {\n    var url = $('#si-url').value.trim();\n    var key = $('#si-key').value;\n\n    if (!url) { result('#si-result', 'Enter the Worker URL', 'bad'); return; }\n    if (!key) { result('#si-result', 'Enter the setup key', 'bad'); return; }\n\n    result('#si-result', 'Signing in…', 'busy');\n    $('#si-go').disabled = true;\n\n    Api.signIn(url, key).then(function () {\n      $('#si-key').value = '';        // never kept, not even in the field\n      $('#si-go').disabled = false;\n      result('#si-result', '');\n      go('dashboard');\n    }, function (e) {\n      $('#si-go').disabled = false;\n      result('#si-result', e.message, 'bad');\n    });\n  });\n\n  $('#si-key').addEventListener('keydown', function (event) {\n    if (event.key === 'Enter') $('#si-go').click();\n  });\n\n  /* ------------------------------------------------------------------ *\n   * 1. Dashboard\n   * ------------------------------------------------------------------ */\n  function renderDashboard() {\n    $('#dash-date').textContent = new Date().toLocaleDateString([], {\n      weekday: 'long', day: 'numeric', month: 'long'\n    });\n    $('#dash-sub').textContent = 'Loading…';\n    $('#ov-list').innerHTML = '<li class=\"emptynote\">Loading…</li>';\n\n    Api.overview().then(function (body) {\n      var t = body.totals;\n      $('#ov-pharmacies').textContent = t.pharmacies;\n      $('#ov-accounts').textContent = t.accounts;\n      $('#ov-vendors').textContent = plural(t.vendors, 'vendor');\n      $('#ov-medicines').textContent = t.medicines;\n      $('#ov-sales').textContent = t.sales;\n      $('#ov-revenue').textContent = money(t.revenue) + ' taken';\n      $('#dash-sub').textContent = t.pharmacies\n        ? plural(t.pharmacies, 'pharmacy', 'pharmacies') + ' · ' + plural(t.accounts, 'account')\n        : 'No pharmacies yet';\n\n      $('#ov-list').innerHTML = body.pharmacies.length\n        ? body.pharmacies.map(pharmacyRow).join('')\n        : '<li class=\"emptynote\">No pharmacies yet.<br>Create the first one from the Pharmacies tab.</li>';\n    }, function (e) {\n      if (handle(e)) return;\n      $('#dash-sub').textContent = 'Could not load';\n      $('#ov-list').innerHTML = '<li class=\"emptynote\">' + escapeHtml(e.message) + '</li>';\n    });\n  }\n\n  function pharmacyRow(p) {\n    var meta = p.reachable === false\n      ? 'Database unreachable'\n      : plural(p.managers || 0, 'manager') + ' · ' + plural(p.vendors || 0, 'vendor') +\n        (p.sales ? ' · ' + plural(p.sales, 'sale') : '');\n\n    return '' +\n      '<li><button class=\"rowcard\" type=\"button\" data-pharmacy=\"' + escapeHtml(p.code) + '\">' +\n        '<span class=\"rowcard__badge' + (p.reachable === false ? ' rowcard__badge--off' : '') + '\">' +\n          escapeHtml(p.code.slice(0, 2).toUpperCase()) + '</span>' +\n        '<span class=\"rowcard__body\">' +\n          '<span class=\"rowcard__name\">' + escapeHtml(p.code) +\n            (p.reachable === false ? ' <span class=\"pill pill--off\">error</span>' : '') + '</span>' +\n          '<span class=\"rowcard__meta\">' + escapeHtml(meta) + '</span>' +\n        '</span>' +\n        '<svg class=\"icon icon--xs rowcard__go\"><use href=\"#i-chevron\"/></svg>' +\n      '</button></li>';\n  }\n\n  $('#dash-refresh').addEventListener('click', function () {\n    renderDashboard();\n    toast('Refreshing…');\n  });\n\n  /* ------------------------------------------------------------------ *\n   * 2. Pharmacies\n   * ------------------------------------------------------------------ */\n  var pharmacyCache = [];\n\n  function renderPharmacies() {\n    $('#ph-sub').textContent = 'Loading…';\n    $('#ph-list').innerHTML = '<li class=\"emptynote\">Loading…</li>';\n\n    Api.pharmacies().then(function (list) {\n      pharmacyCache = list;\n      $('#ph-sub').textContent = list.length\n        ? plural(list.length, 'pharmacy', 'pharmacies')\n        : 'None yet';\n      paintPharmacyList();\n    }, function (e) {\n      if (handle(e)) return;\n      $('#ph-sub').textContent = 'Could not load';\n      $('#ph-list').innerHTML = '<li class=\"emptynote\">' + escapeHtml(e.message) + '</li>';\n    });\n  }\n\n  function paintPharmacyList() {\n    var q = $('#ph-search').value.trim().toLowerCase();\n    var list = q\n      ? pharmacyCache.filter(function (p) { return p.code.indexOf(q) !== -1; })\n      : pharmacyCache;\n\n    $('#ph-list').innerHTML = list.length\n      ? list.map(function (p) {\n          return '' +\n            '<li><button class=\"rowcard\" type=\"button\" data-pharmacy=\"' + escapeHtml(p.code) + '\">' +\n              '<span class=\"rowcard__badge\">' + escapeHtml(p.code.slice(0, 2).toUpperCase()) + '</span>' +\n              '<span class=\"rowcard__body\">' +\n                '<span class=\"rowcard__name\">' + escapeHtml(p.code) + '</span>' +\n                '<span class=\"rowcard__meta\">' + escapeHtml(p.database) +\n                  (p.createdAt ? ' · added ' + ago(p.createdAt) : '') + '</span>' +\n              '</span>' +\n              '<svg class=\"icon icon--xs rowcard__go\"><use href=\"#i-chevron\"/></svg>' +\n            '</button></li>';\n        }).join('')\n      : '<li class=\"emptynote\">' + (q ? 'Nothing matches “' + escapeHtml(q) + '”'\n                                      : 'No pharmacies yet.<br>Create one with the button below.') + '</li>';\n  }\n\n  $('#ph-search').addEventListener('input', paintPharmacyList);\n\n  document.addEventListener('click', function (event) {\n    var btn = event.target.closest('[data-pharmacy]');\n    if (!btn) return;\n    currentPharmacy = btn.dataset.pharmacy;\n    go('detail');\n  });\n\n  /* --------------------------- new pharmacy --------------------------- */\n  $('#ph-add').addEventListener('click', function () {\n    var form = $('#new-form');\n    form.reset();\n    clearBad(form);\n    result('#np-result', '');\n    openSheet(sheets.newPharmacy);\n    $('#np-code').focus({ preventScroll: true });\n  });\n\n  $('#np-cancel').addEventListener('click', closeSheets);\n\n  /* The code is a database name, so it is normalised as it is typed\n     rather than rejected afterwards. */\n  $('#np-code').addEventListener('input', function () {\n    var clean = this.value.toLowerCase().replace(/[^a-z0-9-]+/g, '-');\n    if (clean !== this.value) this.value = clean;\n  });\n\n  $('#new-form').addEventListener('submit', function (event) {\n    event.preventDefault();\n    var form = event.target;\n    clearBad(form);\n\n    var fields = {\n      code: $('#np-code').value.trim(),\n      label: $('#np-label').value.trim(),\n      managerName: $('#np-manager').value.trim(),\n      managerPin: $('#np-pin').value.trim()\n    };\n\n    if (fields.code.replace(/-/g, '').length < 3) {\n      markBad($('#np-code'), 'At least 3 letters or digits'); return;\n    }\n    if (!fields.managerName) { markBad($('#np-manager'), 'The manager needs a name'); return; }\n    if (!/^\\d{4}$/.test(fields.managerPin)) { markBad($('#np-pin'), 'Exactly 4 digits'); return; }\n\n    result('#np-result', 'Creating the database — this takes a few seconds…', 'busy');\n    $('#np-save').disabled = true;\n\n    Api.createPharmacy(fields).then(function (body) {\n      $('#np-save').disabled = false;\n      closeSheets();\n      toast('Created “' + body.pharmacy.code + '”');\n      currentPharmacy = body.pharmacy.code;\n      go('detail');\n    }, function (e) {\n      $('#np-save').disabled = false;\n      if (handle(e)) return;\n      result('#np-result', e.message, 'bad');\n    });\n  });\n\n  /* ------------------------------------------------------------------ *\n   * 3. Pharmacy detail\n   * ------------------------------------------------------------------ */\n  var detailCache = null;\n\n  function renderDetail() {\n    if (!currentPharmacy) { go('pharmacies'); return; }\n\n    $('#dt-code').textContent = currentPharmacy;\n    $('#dt-sub').textContent = 'Loading…';\n    $('#dt-managers').innerHTML = '<li class=\"emptynote\">Loading…</li>';\n    $('#dt-vendors').innerHTML = '';\n\n    Api.pharmacy(currentPharmacy).then(function (body) {\n      detailCache = body;\n\n      $('#dt-sub').textContent = plural(body.accounts.length, 'account') +\n        (body.lastSaleAt ? ' · last sale ' + ago(body.lastSaleAt) : ' · no sales yet');\n      $('#dt-db').textContent = body.database;\n      $('#dt-created').textContent = body.createdAt ? 'Created ' + ago(body.createdAt) : 'Turso database';\n\n      $('#dt-medicines').textContent = body.medicines;\n      $('#dt-units').textContent = plural(body.units || 0, 'unit') + ' on the shelf';\n      $('#dt-sales').textContent = body.sales;\n      $('#dt-revenue').textContent = money(body.revenue) + ' taken';\n\n      var managers = body.accounts.filter(function (a) { return a.role === 'manager'; });\n      var vendors = body.accounts.filter(function (a) { return a.role === 'vendor'; });\n\n      $('#dt-managers').innerHTML = managers.length\n        ? managers.map(accountRow).join('')\n        : '<li class=\"emptynote\">No manager — add one, or nobody can run this pharmacy.</li>';\n      $('#dt-vendors').innerHTML = vendors.length\n        ? vendors.map(accountRow).join('')\n        : '<li class=\"emptynote\">No vendors yet.</li>';\n\n      $('#dt-url').textContent = Api.config().workerUrl || '—';\n      $('#dt-copycode').textContent = body.code;\n    }, function (e) {\n      if (handle(e)) return;\n      $('#dt-sub').textContent = 'Could not load';\n      $('#dt-managers').innerHTML = '<li class=\"emptynote\">' + escapeHtml(e.message) + '</li>';\n    });\n  }\n\n  function accountRow(a) {\n    var badge = a.role === 'manager' ? ' rowcard__badge--mgr' : ' rowcard__badge--vendor';\n    return '' +\n      '<li><button class=\"rowcard\" type=\"button\" data-account=\"' + escapeHtml(a.id) + '\">' +\n        '<span class=\"rowcard__badge' + (a.active ? badge : ' rowcard__badge--off') + '\">' +\n          escapeHtml(initials(a.name)) + '</span>' +\n        '<span class=\"rowcard__body\">' +\n          '<span class=\"rowcard__name\">' + escapeHtml(a.name) +\n            (a.active ? '' : ' <span class=\"pill pill--off\">off</span>') + '</span>' +\n          '<span class=\"rowcard__meta\">' + (a.role === 'manager' ? 'Manager' : 'Vendor') +\n            ' · added ' + ago(a.createdAt) + '</span>' +\n        '</span>' +\n        '<svg class=\"icon icon--xs rowcard__go\"><use href=\"#i-pen\"/></svg>' +\n      '</button></li>';\n  }\n\n  /* --------------------------- account sheet -------------------------- */\n  var editingAccount = null;\n  var editingRole = 'vendor';\n\n  $$('[data-add-role]').forEach(function (btn) {\n    btn.addEventListener('click', function () {\n      editingAccount = null;\n      editingRole = btn.dataset.addRole;\n      openAccountSheet();\n    });\n  });\n\n  document.addEventListener('click', function (event) {\n    var btn = event.target.closest('[data-account]');\n    if (!btn || !detailCache) return;\n    editingAccount = detailCache.accounts.filter(function (a) { return a.id === btn.dataset.account; })[0] || null;\n    if (!editingAccount) return;\n    editingRole = editingAccount.role;\n    openAccountSheet();\n  });\n\n  function openAccountSheet() {\n    var form = $('#acct-form');\n    form.reset();\n    clearBad(form);\n    result('#ac-result', '');\n\n    var isEdit = Boolean(editingAccount);\n    $('#ac-title').textContent = isEdit\n      ? editingAccount.name\n      : (editingRole === 'manager' ? 'Add manager' : 'Add vendor');\n    $('#ac-name').value = isEdit ? editingAccount.name : '';\n    $('#ac-active').checked = isEdit ? editingAccount.active : true;\n    $('#ac-active-row').hidden = !isEdit;\n    $('#ac-remove').hidden = !isEdit;\n\n    // On an existing account a blank PIN means \"leave it alone\", so the\n    // label has to say which of the two this is.\n    $('#ac-pin-label').textContent = isEdit ? 'New PIN (blank to keep the current one)' : '4-digit PIN';\n    $('#ac-pin').placeholder = isEdit ? '••••' : '1234';\n\n    openSheet(sheets.account);\n    // preventScroll for the same reason the body is pinned: focusing a\n    // field in a sheet that is still animating in must not scroll anything.\n    if (!isEdit) $('#ac-name').focus({ preventScroll: true });\n  }\n\n  $('#ac-cancel').addEventListener('click', closeSheets);\n\n  $('#acct-form').addEventListener('submit', function (event) {\n    event.preventDefault();\n    clearBad(event.target);\n\n    var name = $('#ac-name').value.trim();\n    var pin = $('#ac-pin').value.trim();\n    var active = $('#ac-active').checked;\n\n    if (!name) { markBad($('#ac-name'), 'A name is required'); return; }\n    if (!editingAccount && !/^\\d{4}$/.test(pin)) { markBad($('#ac-pin'), 'Exactly 4 digits'); return; }\n    if (editingAccount && pin && !/^\\d{4}$/.test(pin)) { markBad($('#ac-pin'), 'Exactly 4 digits, or leave blank'); return; }\n\n    result('#ac-result', 'Saving…', 'busy');\n    $('#ac-save').disabled = true;\n\n    var done = function (message) {\n      $('#ac-save').disabled = false;\n      closeSheets();\n      toast(message);\n      renderDetail();\n    };\n    var failed = function (e) {\n      $('#ac-save').disabled = false;\n      if (handle(e)) return;\n      result('#ac-result', e.message, 'bad');\n    };\n\n    if (editingAccount) {\n      var patch = { name: name, active: active };\n      if (pin) patch.pin = pin;\n      Api.updateAccount(currentPharmacy, editingAccount.id, patch)\n        .then(function () { done(name + ' updated'); }, failed);\n    } else {\n      Api.createAccount(currentPharmacy, { name: name, pin: pin, role: editingRole })\n        .then(function () { done(name + ' added'); }, failed);\n    }\n  });\n\n  $('#ac-remove').addEventListener('click', function () {\n    if (!editingAccount) return;\n    result('#ac-result', 'Removing…', 'busy');\n    Api.removeAccount(currentPharmacy, editingAccount.id).then(function (body) {\n      closeSheets();\n      toast(body.message || 'Removed');\n      renderDetail();\n    }, function (e) {\n      if (handle(e)) return;\n      result('#ac-result', e.message, 'bad');\n    });\n  });\n\n  /* --------------------------- archiving ------------------------------ *\n   * Two guards, because one of these two outcomes destroys records that\n   * cannot be got back: the code has to be typed out, and deleting the\n   * database is a separate switch that is off by default.\n   * ------------------------------------------------------------------ */\n  $('#dt-archive').addEventListener('click', function () {\n    if (!currentPharmacy) return;\n    $('#cf-title').textContent = 'Archive “' + currentPharmacy + '”?';\n    $('#cf-body').textContent =\n      'Phones will stop being able to reach this pharmacy. By default its database is kept, ' +\n      'so the records survive and it can be restored by creating it again with the same code.';\n    $('#cf-drop').checked = false;\n    $('#cf-type').value = '';\n    $('#cf-type').placeholder = currentPharmacy;\n    result('#cf-result', '');\n    $('#cf-go').textContent = 'Archive';\n    openSheet(sheets.confirm);\n  });\n\n  $('#cf-drop').addEventListener('change', function () {\n    $('#cf-go').textContent = this.checked ? 'Delete everything' : 'Archive';\n    $('#cf-body').textContent = this.checked\n      ? 'This deletes the Turso database and every record in it — stock, sales and prescriptions. ' +\n        'There is no undo and no backup.'\n      : 'Phones will stop being able to reach this pharmacy. By default its database is kept, ' +\n        'so the records survive and it can be restored by creating it again with the same code.';\n    $('#cf-body').className = 'sheet__note ' + (this.checked ? 'sheet__note--warn' : 'sheet__note--info');\n  });\n\n  $('#cf-cancel').addEventListener('click', closeSheets);\n\n  $('#cf-go').addEventListener('click', function () {\n    if ($('#cf-type').value.trim() !== currentPharmacy) {\n      result('#cf-result', 'Type “' + currentPharmacy + '” exactly to confirm', 'bad');\n      return;\n    }\n\n    var drop = $('#cf-drop').checked;\n    result('#cf-result', drop ? 'Deleting…' : 'Archiving…', 'busy');\n    $('#cf-go').disabled = true;\n\n    Api.archivePharmacy(currentPharmacy, drop).then(function (body) {\n      $('#cf-go').disabled = false;\n      closeSheets();\n      toast(body.message || 'Done');\n      currentPharmacy = null;\n      go('pharmacies');\n    }, function (e) {\n      $('#cf-go').disabled = false;\n      if (handle(e)) return;\n      result('#cf-result', e.message, 'bad');\n    });\n  });\n\n  /* ------------------------------------------------------------------ *\n   * 4. Settings\n   * ------------------------------------------------------------------ */\n  function renderSettings() {\n    $('#st-url').value = Api.config().workerUrl || '';\n    result('#st-url-result', '');\n    result('#st-turso-result', '');\n    loadConfig();\n  }\n\n  function loadConfig() {\n    $('#st-source').textContent = 'Loading…';\n    $('#st-checklist').innerHTML = '<li class=\"emptynote\">Loading…</li>';\n\n    Api.getConfig().then(function (c) {\n      $('#st-org').value = c.org.value || '';\n      $('#st-group').value = c.group.value || 'default';\n      $('#st-token').value = '';\n\n      // Where a value came from decides whether editing it here does\n      // anything at all, so it is stated rather than implied.\n      $('#st-source').textContent = c.platformToken.source === 'worker-secret'\n        ? 'These come from Worker secrets set with wrangler. Editing them here has no effect until those are removed.'\n        : c.platformToken.set\n          ? 'These were set from this app and are stored by the Worker.'\n          : 'Not configured yet. Fill these in to create pharmacies.';\n      $('#st-source').className = 'sheet__note ' +\n        (c.platformToken.source === 'worker-secret' ? 'sheet__note--info'\n          : c.platformToken.set ? 'sheet__note--info' : 'sheet__note--warn');\n\n      $('#st-checklist').innerHTML = [\n        check('Turso organisation', c.org.set !== false && c.org.value, c.org.value\n          ? 'Set to “' + c.org.value + '”' + sourceNote(c.org.source)\n          : 'Needed before a pharmacy can be created.'),\n        check('Turso group', Boolean(c.group.value), 'Databases are created in “' + (c.group.value || 'default') + '”.'),\n        check('Platform token', c.platformToken.set,\n          c.platformToken.set ? 'Set' + sourceNote(c.platformToken.source)\n            : 'Needed before a pharmacy can be created.'),\n        check('Session secret', c.sessionSecret.set,\n          c.sessionSecret.set ? 'Signs sign-in tokens.'\n            : 'Nobody can sign in until this is set: <code>wrangler secret put SESSION_SECRET</code>'),\n        check('Setup key', c.setupKey.set,\n          c.setupKey.set ? 'What you signed in with.' : '<code>wrangler secret put SETUP_KEY</code>'),\n        check('KV namespace', c.kv.set,\n          c.kv.set ? 'Where the pharmacy index lives.' : 'Bind PHARMACIES in wrangler.toml.')\n      ].join('');\n    }, function (e) {\n      if (handle(e)) return;\n      $('#st-source').textContent = e.message;\n      $('#st-checklist').innerHTML = '<li class=\"emptynote\">' + escapeHtml(e.message) + '</li>';\n    });\n  }\n\n  function sourceNote(source) {\n    if (source === 'worker-secret') return ' · from a Worker secret';\n    if (source === 'admin-app') return ' · set from this app';\n    return '';\n  }\n\n  function check(name, ok, why) {\n    return '' +\n      '<li class=\"chk\">' +\n        '<span class=\"chk__dot chk__dot--' + (ok ? 'ok' : 'no') + '\">' +\n          '<svg class=\"icon icon--xs\"><use href=\"#i-' + (ok ? 'check' : 'alert') + '\"/></svg></span>' +\n        '<span class=\"chk__name\">' + escapeHtml(name) + '</span>' +\n        '<span class=\"pill pill--' + (ok ? 'ok' : 'off') + '\">' + (ok ? 'set' : 'missing') + '</span>' +\n        '<span class=\"chk__why\">' + why + '</span>' +\n      '</li>';\n  }\n\n  $('#st-check').addEventListener('click', function () {\n    var url = $('#st-url').value.trim();\n    if (!url) { result('#st-url-result', 'Enter the Worker URL first', 'bad'); return; }\n    result('#st-url-result', 'Checking…', 'busy');\n    Api.health(url).then(function (body) {\n      result('#st-url-result', 'Worker is up (v' + body.version + ')', 'ok');\n    }, function (e) {\n      result('#st-url-result', e.message, 'bad');\n    });\n  });\n\n  $('#st-save-url').addEventListener('click', function () {\n    var url = $('#st-url').value.trim();\n    if (!url) { result('#st-url-result', 'Enter the Worker URL first', 'bad'); return; }\n    Api.configure({ workerUrl: url });\n    result('#st-url-result', 'Saved', 'ok');\n    toast('Worker URL saved');\n  });\n\n  $('#st-save-turso').addEventListener('click', function () {\n    var fields = { org: $('#st-org').value.trim(), group: $('#st-group').value.trim() || 'default' };\n    // A blank token means \"keep the current one\", so it is only sent when\n    // something was actually typed.\n    var token = $('#st-token').value.trim();\n    if (token) fields.token = token;\n\n    if (!fields.org) { result('#st-turso-result', 'Enter the Turso organisation', 'bad'); return; }\n\n    result('#st-turso-result', 'Saving…', 'busy');\n    Api.putConfig(fields).then(function () {\n      $('#st-token').value = '';\n      result('#st-turso-result', 'Saved. Press Test to confirm Turso accepts it.', 'ok');\n      loadConfig();\n    }, function (e) {\n      if (handle(e)) return;\n      result('#st-turso-result', e.message, 'bad');\n    });\n  });\n\n  $('#st-test').addEventListener('click', function () {\n    result('#st-turso-result', 'Asking Turso…', 'busy');\n    Api.testTurso().then(function (body) {\n      result('#st-turso-result', body.message, body.ok ? 'ok' : 'bad');\n    }, function (e) {\n      if (handle(e)) return;\n      result('#st-turso-result', e.message, 'bad');\n    });\n  });\n\n  $('#st-signout').addEventListener('click', function () {\n    Api.signOut();\n    go('signin');\n    toast('Signed out');\n  });\n\n  /* ------------------------------------------------------------------ *\n   * Boot\n   * ------------------------------------------------------------------ */\n  go(Api.signedIn() ? 'dashboard' : 'signin');\n})();\n\n</script>\n</body>\n</html>\n";
